#include <FastLED.h>
#include <EEPROM.h>
#include <WiFi.h>
#include <WebServer.h>
#include <DNSServer.h>

#define LED_PIN    4     // Порт для светодиодной ленты GPIO 4
#define BUTTON_PIN  2    
#define NUM_LEDS    100   // Настройки под ваши 100 диодов

#define EEPROM_MODE_ADDR 0    
#define EEPROM_BRIGHT_ADDR 1  // Адрес для сохранения яркости
#define EEPROM_SIZE      4    

// Настройки Wi-Fi точки доступа
const char* ssid = "ESP32-Led-TAG";
const char* password = "tag"; 

// Сетевые настройки для стабильного подключения
IPAddress local_ip(192, 168, 4, 1);
IPAddress gateway(192, 168, 4, 1);
IPAddress subnet(255, 255, 255, 0);

DNSServer dnsServer; 
WebServer server(80); 
CRGB leds[NUM_LEDS];     

byte colorMode = 0;       
byte maxBrightness = 255; 
bool lastButtonState = HIGH;
bool systemHardLocked = false; 
unsigned long lastDebounceTime = 0;

uint32_t getCurrentColorHex(byte mode) {
  switch (mode) {
    case 0: return 0xff0000; // Красный
    case 1: return 0xff9900; // Оранжевый
    case 2: return 0xffff00; // Желтый
    case 3: return 0x00ff00; // Зеленый
    case 4: return 0x00ffff; // Голубой
    case 5: return 0x0000ff; // Синий
    case 6: return 0xff00ff; // Пурпурный
    case 7: return 0x9900ff; // Фиолетовый
    case 8: return 0xFF4500; // Оранжево-красный
    case 9: return 0x000000; // Выключено
    default: return 0xff0000;
  }
}

const char* getColorName(byte mode) {
  switch (mode) {
    case 0: return "Красный";
    case 1: return "Оранжевый";
    case 2: return "Желтый";
    case 3: return "Зеленый";
    case 4: return "Голубой";
    case 5: return "Синий";
    case 6: return "Пурпурный";
    case 7: return "Фиолетовый";
    case 8: return "Оранжево-красный";
    case 9: return "Выключено";
    default: return "Неизвестно";
  }
}

void showCurrentColor() {
  fill_solid(leds, NUM_LEDS, getCurrentColorHex(colorMode));
  FastLED.show();
}

void changeMode(byte newMode) {
  if (systemHardLocked) return; 

  colorMode = newMode;
  if (colorMode > 9) {
    colorMode = 0;
  }

  EEPROM.write(EEPROM_MODE_ADDR, colorMode);
  EEPROM.commit();

  FastLED.setBrightness(maxBrightness); 
  showCurrentColor(); 
}

// Генерация страницы сайта
void handleRoot() {
  String html = "<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1.0'>";
  html += "<title>ESP32 LED</title><style>";
  html += "body { font-family: sans-serif; text-align: center; background-color: #222; color: #fff; padding: 20px 10px; }";
  html += ".btn { display: inline-block; width: 85%; max-width: 300px; padding: 15px; margin: 8px; font-size: 18px; border: none; border-radius: 8px; cursor: pointer; color: white; font-weight: bold; text-decoration: none; }";
  html += ".active { border: 3px solid #fff; box-shadow: 0 0 15px #fff; }";
  html += ".slider { width: 85%; max-width: 300px; height: 15px; border-radius: 5px; background: #d3d3d3; outline: none; margin: 20px 0; }";
  html += ".btn-lock { background-color: #d9534f; box-shadow: 0 4px #999; }";
  html += ".btn-lock:active { background-color: #c9302c; box-shadow: 0 2px #666; transform: translateY(2px); }";
  html += "</style></head><body>";

  if (systemHardLocked) {
    html += "<h2>Управление заблокировано!</h2>";
    html += "<p style='color:#ff6666;'>Связь удерживается, но команды кнопок и сайта отключены.</p>";
    html += "</body></html>";
    server.send(200, "text/html", html);
    return;
  }

  html += "<h2>Управление подсветкой</h2>";
  html += "<p>Текущий режим: <b>" + String(getColorName(colorMode)) + "</b></p>";

  // Ползунок яркости
  html += "<p>Яркость: <span id='val'>" + String(maxBrightness) + "</span></p>";
  html += "<input type='range' min='10' max='255' value='" + String(maxBrightness) + "' class='slider' id='brightRange' onchange='sendBright(this.value)'>";
  html += "<br>";

  // Кнопки управления
  html += "<a href='/set?mode=0' class='btn " + String(colorMode == 0 ? "active" : "") + "' style='background-color: #ff0000;'>Красный</a><br>";
  html += "<a href='/set?mode=1' class='btn " + String(colorMode == 1 ? "active" : "") + "' style='background-color: #ff9900;'>Оранжевый</a><br>";
  html += "<a href='/set?mode=2' class='btn " + String(colorMode == 2 ? "active" : "") + "' style='background-color: #ffff00; color: black;'>Желтый</a><br>";
  html += "<a href='/set?mode=3' class='btn " + String(colorMode == 3 ? "active" : "") + "' style='background-color: #00ff00; color: black;'>Зеленый</a><br>";
  html += "<a href='/set?mode=4' class='btn " + String(colorMode == 4 ? "active" : "") + "' style='background-color: #00ffff; color: black;'>Голубой</a><br>";
  html += "<a href='/set?mode=5' class='btn " + String(colorMode == 5 ? "active" : "") + "' style='background-color: #0000ff;'>Синий</a><br>";
  html += "<a href='/set?mode=6' class='btn " + String(colorMode == 6 ? "active" : "") + "' style='background-color: #ff00ff;'>Пурпурный</a><br>";
  html += "<a href='/set?mode=7' class='btn " + String(colorMode == 7 ? "active" : "") + "' style='background-color: #9900ff;'>Фиолетовый</a><br>";
  html += "<a href='/set?mode=8' class='btn " + String(colorMode == 8 ? "active" : "") + "' style='background-color: #FF4500;'>Оранжево-красный</a><br><br>";
  html += "<a href='/set?mode=9' class='btn " + String(colorMode == 9 ? "active" : "") + "' style='background-color: #000;'>ВЫКЛЮЧИТЬ</a><br><br>";

  // Кнопка блокировки
  html += "<hr style='width:85%; border:1px solid #444;'><br>";
  html += "<a href='/lock' class='btn btn-lock' onclick='return confirm(\"Заблокировать все кнопки и сайт?\")'>БЛОКИРОВКА УПРАВЛЕНИЯ</a><br>";

  html += "<script>function sendBright(val){document.getElementById('val').innerText=val; fetch('/brightness?value='+val);}</script>";
  html += "</body></html>";
  server.send(200, "text/html", html);
}

void handleSetMode() {
  if (!systemHardLocked && server.hasArg("mode")) {
    int targetMode = server.arg("mode").toInt();
    if (targetMode >= 0 && targetMode <= 9) {
      changeMode(targetMode);
    }
  }
  server.sendHeader("Location", "/");
  server.send(303);
}

void handleBrightness() {
  if (!systemHardLocked && server.hasArg("value")) {
    int b = server.arg("value").toInt();
    if (b >= 10 && b <= 255) {
      maxBrightness = b;
      FastLED.setBrightness(maxBrightness);
      FastLED.show();
      EEPROM.write(EEPROM_BRIGHT_ADDR, maxBrightness);
      EEPROM.commit();
    }
  }
  server.send(200, "text/plain", "OK");
}

void handleLock() {
  systemHardLocked = true;
  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  EEPROM.begin(EEPROM_SIZE); 

  FastLED.addLeds<WS2812B, LED_PIN, GRB>(leds, NUM_LEDS);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  colorMode = EEPROM.read(EEPROM_MODE_ADDR);
  if (colorMode > 9) colorMode = 0;

  maxBrightness = EEPROM.read(EEPROM_BRIGHT_ADDR);
  if (maxBrightness < 10 || maxBrightness > 255) maxBrightness = 255;

  FastLED.setBrightness(maxBrightness);
  showCurrentColor();

  // Настройка собственной Wi-Fi сети
  WiFi.mode(WIFI_AP);
  WiFi.softAPConfig(local_ip, gateway, subnet);
  WiFi.softAP(ssid, password);

  // Включаем перенаправление (Captive Portal)
  dnsServer.start(53, "*", local_ip);

  server.on("/", handleRoot);
  server.on("/set", handleSetMode);
  server.on("/brightness", handleBrightness);
  server.on("/lock", handleLock);

  // Если телефон просит системные страницы проверки сети, кидаем его на наш сайт
  server.onNotFound(handleRoot); 
  server.begin();
}

void loop() {
  dnsServer.processNextRequest(); // Постоянно обрабатываем запросы перенаправления
  server.handleClient();

  if (systemHardLocked) {
    return; 
  }

  bool currentButtonState = digitalRead(BUTTON_PIN);
  unsigned long currentMillis = millis();

  if (currentButtonState == LOW && lastButtonState == HIGH) {
    if (currentMillis - lastDebounceTime > 150) { 
      lastDebounceTime = currentMillis;

      byte nextMode = colorMode + 1;
      if (nextMode > 9) nextMode = 0;
      changeMode(nextMode);
    }
  }
  lastButtonState = currentButtonState;
}
